import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

public class Solution {
    record Evento(String id, String agregadoId, String tipo, String payload) {}

    static class Outbox {
        private final List<Evento> eventos = new ArrayList<>();
        private final Set<String> enviados = new HashSet<>();
        private final Set<String> publicados = new HashSet<>();

        void registrar(Evento evento) {
            if (evento == null || !enviados.add(evento.id())) return;
            eventos.add(evento);
        }

        List<Evento> pendentes(int limite) {
            var out = new ArrayList<Evento>();
            for (var e : eventos) {
                if (out.size() >= limite) break;
                if (!publicados.contains(e.id())) out.add(e);
            }
            return out;
        }

        void marcarPublicado(String eventoId) {
            publicados.add(eventoId);
        }

        int pendentesCount() {
            int total = 0;
            for (var e : eventos) if (!publicados.contains(e.id())) total++;
            return total;
        }
    }

    static class BrokerFake {
        private final List<Evento> eventos = new ArrayList<>();
        private boolean falharProxima = false;

        void publicar(Evento evento) {
            if (falharProxima) {
                falharProxima = false;
                throw new IllegalStateException("falha simulada no broker");
            }
            eventos.add(evento);
        }

        List<Evento> eventos() { return List.copyOf(eventos); }
        void falharProximaPublicacao() { falharProxima = true; }
    }

    static class Relay {
        private final Outbox outbox;
        private final BrokerFake broker;
        private final int limite;

        Relay(Outbox outbox, BrokerFake broker, int limite) {
            this.outbox = outbox;
            this.broker = broker;
            this.limite = limite;
        }

        int publicarPendentes() {
            int publicados = 0;
            for (var evento : outbox.pendentes(limite)) {
                try {
                    broker.publicar(evento);
                } catch (RuntimeException e) {
                    break;
                }
                outbox.marcarPublicado(evento.id());
                publicados++;
            }
            return publicados;
        }
    }

    static class ConsumidorIdempotente {
        private final BrokerFake broker;
        private final Set<String> vistos = new HashSet<>();
        private final List<String> processados = new ArrayList<>();
        private int cursor = 0;

        ConsumidorIdempotente(BrokerFake broker) {
            this.broker = broker;
        }

        int processar() {
            int novos = 0;
            var eventos = broker.eventos();
            while (cursor < eventos.size()) {
                var evento = eventos.get(cursor++);
                if (vistos.add(evento.id())) {
                    processados.add(evento.id());
                    novos++;
                }
            }
            return novos;
        }

        List<String> processados() { return List.copyOf(processados); }
    }
}

