import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import java.util.List;

class SolutionTest {
    private Solution.Evento e(String id) {
        return new Solution.Evento(id, "ag-1", "PedidoCriado", "{}");
    }

    @Test void relayPublicaEMarca() {
        var outbox = new Solution.Outbox();
        var broker = new Solution.BrokerFake();
        outbox.registrar(e("e1"));
        outbox.registrar(e("e2"));
        var relay = new Solution.Relay(outbox, broker, 10);
        assertEquals(2, relay.publicarPendentes());
        assertEquals(0, outbox.pendentesCount());
        assertEquals(List.of("e1", "e2"), broker.eventos().stream().map(Solution.Evento::id).toList());
    }

    @Test void falhaDeixaEventoPendenteEPodeRepetir() {
        var outbox = new Solution.Outbox();
        var broker = new Solution.BrokerFake();
        outbox.registrar(e("e1"));
        broker.falharProximaPublicacao();
        var relay = new Solution.Relay(outbox, broker, 10);
        assertEquals(0, relay.publicarPendentes());
        assertEquals(1, outbox.pendentesCount());
        assertEquals(1, relay.publicarPendentes());
        assertEquals(0, outbox.pendentesCount());
    }

    static class BrokerQueFalhaNoSegundo extends Solution.BrokerFake {
        int chamadas = 0;

        @Override
        public void publicar(Solution.Evento evento) {
            if (++chamadas == 2) throw new IllegalStateException("falha no segundo");
            super.publicar(evento);
        }
    }

    @Test void falhaNoSegundoMantemRestantePendente() {
        var outbox = new Solution.Outbox();
        var broker = new BrokerQueFalhaNoSegundo();
        outbox.registrar(e("e1"));
        outbox.registrar(e("e2"));
        outbox.registrar(e("e3"));
        var relay = new Solution.Relay(outbox, broker, 10);
        assertEquals(1, relay.publicarPendentes());
        assertEquals(1, broker.eventos().size());
        assertEquals(2, outbox.pendentesCount());
        assertEquals(2, relay.publicarPendentes());
        assertEquals(3, broker.eventos().size());
        assertEquals(0, outbox.pendentesCount());
    }

    @Test void registrarIdRepetidoNaoDuplica() {
        var outbox = new Solution.Outbox();
        outbox.registrar(e("e1"));
        outbox.registrar(e("e1"));
        assertEquals(1, outbox.pendentesCount());
    }

    @Test void consumidorDeduplica() {
        var broker = new Solution.BrokerFake();
        broker.publicar(e("e1"));
        broker.publicar(e("e2"));
        broker.publicar(e("e1"));
        var consumidor = new Solution.ConsumidorIdempotente(broker);
        assertEquals(2, consumidor.processar());
        assertEquals(List.of("e1", "e2"), consumidor.processados());
        assertEquals(0, consumidor.processar());
    }

    @Test void limiteDoRelayEhRespeitado() {
        var outbox = new Solution.Outbox();
        var broker = new Solution.BrokerFake();
        for (int i = 1; i <= 5; i++) outbox.registrar(e("e" + i));
        var relay = new Solution.Relay(outbox, broker, 2);
        assertEquals(2, relay.publicarPendentes());
        assertEquals(3, outbox.pendentesCount());
    }
}
